const N:usize=64;const MAX_ARCS:usize=N*(N-1);
unsafe fn put(out:*mut u8,i:usize,v:i64){let b=v as u64;for j in 0..8{*out.add(i*8+j)=(b>>(8*j)) as u8}}
#[no_mangle] pub unsafe extern "C" fn bidirectional_search(input:*const i64,len:usize,out:*mut u8,cap:usize)->i64{if input.is_null()||len<4{return -1}let a=std::slice::from_raw_parts(input,len);if a[0]<1||a[0]>N as i64{return -1}let n=a[0] as usize;if a[1]<0||a[1]>=n as i64||a[2]<0||a[2]>=n as i64||a[3]<0||a[3]>MAX_ARCS as i64||len!=4+2*a[3] as usize{return -1}let m=a[3] as usize;
 let mut adj=[[0usize;N-1];N];let mut deg=[0usize;N];let mut edge=[[false;N];N];for i in 0..m{let u=a[4+2*i];let v=a[5+2*i];if u<0||u>=n as i64||v<0||v>=n as i64||u==v as i64{return -1}let(u,v)=(u as usize,v as usize);if edge[u][v]{return -1}edge[u][v]=true;adj[u][deg[u]]=v;deg[u]+=1}for u in 0..n{for v in 0..n{if edge[u][v]!=edge[v][u]{return -1}}}
 let(start,goal)=(a[1] as usize,a[2] as usize);let mut path=[0usize;N];let mut pc=0;if start==goal{path[pc]=start;pc+=1}else{let mut parent=[[-2i32;N];2];let mut q=[[0usize;N];2];let mut head=[0usize;2];let mut tail=[0usize;2];parent[0][start]= -1;parent[1][goal]= -1;q[0][0]=start;q[1][0]=goal;tail=[1,1];let mut meet=None;while head[0]<tail[0]&&head[1]<tail[1]&&meet.is_none(){for s in 0..2{if meet.is_some(){break}let cur=q[s][head[s]];head[s]+=1;for j in 0..deg[cur]{let v=adj[cur][j];if parent[s][v]!=-2{continue}parent[s][v]=cur as i32;q[s][tail[s]]=v;tail[s]+=1;if parent[1-s][v]!=-2{meet=Some(v);break}}}}if let Some(v)=meet{let mut rev=[0usize;N];let mut k=0;let mut x=v as i32;while x!=-1{rev[k]=x as usize;k+=1;x=parent[0][x as usize]}for i in (0..k).rev(){path[pc]=rev[i];pc+=1}let mut x=parent[1][v];while x!=-1{path[pc]=x as usize;pc+=1;x=parent[1][x as usize]}}}
 let bytes=(1+pc)*8;if out.is_null()||cap<bytes{return -2}put(out,0,pc as i64);for i in 0..pc{put(out,1+i,path[i] as i64)}bytes as i64}
